  [8288] = { "対象の魂を吸い取り、$D1かけて$N1のShadowダメージを与えます。Drain Soulでダメージを受けた、経験値か名誉を得られる対象は、Soul Shardをもたらすことがあります。Drain Soulで倒された、経験値か名誉を得られる対象は、必ずSoul Shardをもたらします。Soul Shardは他の呪文に必要です。", "$N2秒ごとに$N1のShadowダメージを受けます。", 0x0ad8031e, 0x774bc67a, "uu" },
  [8289] = { "対象の魂を吸い取り、$D1かけて$N1のShadowダメージを与えます。Drain Soulでダメージを受けた、経験値か名誉を得られる対象は、Soul Shardをもたらすことがあります。Drain Soulで倒された、経験値か名誉を得られる対象は、必ずSoul Shardをもたらします。Soul Shardは他の呪文に必要です。", "$N2秒ごとに$N1のShadowダメージを受けます。", 0x0ad8031e, 0x774bc67a, "uu" },
  [8312] = { "$D1の間、対象を動けなくします。", "根を張られて動けません。", 0x73de166e, 0x9bb1efcf, "uu" },
  [8313] = { "対象を毒に侵し、$D2の間、$N2秒ごとに$N1のNatureダメージを与えます。", "$N2秒ごとに$N1のNatureダメージを受けます。", 0xc6bab046, 0xf6322bec, "uu" },
  [8316] = { "対象を炎の盾で包みます。対象への攻撃があるたびに、攻撃者に$N1のFireダメージを与えます。効果時間は$D1です。ペットは自身にFire Shieldをかけられません。", "攻撃を受けると、攻撃者に$N1のFireダメージを与えます。", 0x9dc0d206, 0x8a7fa492, "uu" },
  [8317] = { "対象を炎の盾で包みます。対象への攻撃があるたびに、攻撃者に$N1のFireダメージを与えます。効果時間は$D1です。ペットは自身にFire Shieldをかけられません。", "攻撃を受けると、攻撃者に$N1のFireダメージを与えます。", 0x9dc0d206, 0x8a7fa492, "uu" },
  [8331] = { "Non-Engineersのための、ほぼ必ず標的に届くダイナマイト！半径5ヤードに$N1のFireダメージを与えます。", nil, 0xdafab22b, nil, "um" },
  [8334] = { "最大125の最大、工学のあなたのスキルを向上させるために時計ボックスを分解します。", nil, 0x3cc67cd2, nil, "um" },
  [8339] = { "ほぼ常にターゲットに到達する非エンジニアのためのダイナマイト！ 5ヤードの半径の51から69ファイアダメージを与えます。", nil, 0xfa27a5d9, nil, "um" },
  [8342] = { "Jumper Cablesは、死んだプレイヤーに電気ショックを与えて蘇生させられることがあります。戦闘中は使用できません。", nil, 0x69f96d99, nil, "um" },
  [8344] = { "機械の対象を短時間操作できます。うまくいかないこともあり、機械をその場に固定するだけだったり、機械をひどく怒らせたりすることもあります。ノームの工学の最高傑作です。", nil, 0xfd425ee0, nil, "um" },
  [8348] = { "$D1かけて使用者のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0xaf16c71a, 0xb325951b, "uu" },
  [8375] = { "手袋に永続的なエンチャントを施し、Miningスキルを+$N1します。", nil, 0xb95cea17, nil, "um" },
  [8380] = { "対象のアーマーを削り、Sunder Armorごとに$N1下げ、大量の脅威を発生させます。最大5回まで重ねられます。効果時間は$D1です。", "アーマーが$N1低下しています。", 0x03bf3c06, 0x57b604c7, "uu" },
  [8387] = { "近くの薬草の茂みがミニマップに表示されます。同時に追跡できるものは1種類だけです。", "Herbsを探しています。", 0xeccadd57, 0x5c5cf54a, "uu" },
  [8388] = { "近くの鉱脈がミニマップに表示されます。同時に追跡できるものは1種類だけです。", "Mineralsを探しています。", 0xe377a8db, 0x047b9927, "uu" },
