  [8397] = { "近接攻撃を受けたとき$N1%の確率で聖なる盾を得て、$D1の間$N2のダメージを吸収します。この確率はWastelandとHauntedの地域では倍になります。", nil, 0x0de35ba5, nil, "um" },
  [8400] = { "火の玉を投げつけ、$N1のFireダメージと、$D1かけてさらに$N2のFireダメージを与えます。", "$N2秒ごとに$N1のFireダメージを受けます。", 0xdbc51345, 0xa1772ba6, "uu" },
