  [8461] = { { "$N1のFrostダメージを吸収します。さらに$N2%の確率でFrostの呪文と効果を反射します。効果時間は$D1です。", "$N1のFrostダメージを吸収します。効果時間は$D1です。", shape = { "3/1", "2/1" } }, { "Frostダメージを$N1吸収します。$N2%の確率でFrostの呪文と効果を反射します。", "Frostダメージを$N1吸収します。", shape = { "2/0", "1/0" } }, 0x388bceec, 0x7185f7be, "uu" },
  [8462] = { { "$N1のFrostダメージを吸収します。さらに$N2%の確率でFrostの呪文と効果を反射します。効果時間は$D1です。", "$N1のFrostダメージを吸収します。効果時間は$D1です。", shape = { "3/1", "2/1" } }, { "Frostダメージを$N1吸収します。$N2%の確率でFrostの呪文と効果を反射します。", "Frostダメージを$N1吸収します。", shape = { "2/0", "1/0" } }, 0x388bceec, 0x7185f7be, "uu" },
