  [8649] = { "フィニッシュ技。$D1の間、対象の守りを崩し、コンボポイントに応じてアーマーを減少させます：\n 1ポイント：$N3 アーマー\n 2ポイント：$N5 アーマー\n 3ポイント：$N7 アーマー\n 4ポイント：$N9 アーマー\n 5ポイント：$N11 アーマー", "アーマーが$N1低下しています。", 0x3018a352, 0x57b710eb, "uu" },
